package dev.gbppimentel.snapcompanion.next;
import android.content.Context;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.util.ReflectionHelpers;import static org.junit.Assert.*;
/** Actual UI delivery boundary without a root reader, device input or scheduled polling. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=33)
public class ControllerFeedBoundaryTest {
 private ControllerFeed feed;private Context context;private GameConnection old;private boolean active;
 @Before public void setup(){context=RuntimeEnvironment.getApplication();context.getSharedPreferences("snap",0).edit().clear().commit();old=EdenLinkService.connection;active=EdenLinkService.active;EdenLinkService.active=true;EdenLinkService.connection=GameConnection.empty().observed("123",true,System.currentTimeMillis());feed=new ControllerFeed(context,j->{});ReflectionHelpers.setField(feed,"owner","activity1");ReflectionHelpers.setField(feed,"session","reader1");ReflectionHelpers.setField(feed,"source","default:"+EdenLinkService.connection.token());}
 @After public void cleanup(){feed.stop();EdenLinkService.connection=old;EdenLinkService.active=active;}
 private String frame(String token,boolean available){return "{\"token\":\""+token+"\",\"available\":"+available+",\"buttons\":{\"A\":true}}";}
 @Test public void queuedCallbacksCannotCrossStopReopenOrReaderRotation(){String oldFrame=frame("reader1",true);assertTrue(feed.current(oldFrame));feed.stop();assertFalse(feed.current(oldFrame));ReflectionHelpers.setField(feed,"owner","activity2");ReflectionHelpers.setField(feed,"session","reader2");ReflectionHelpers.setField(feed,"source","default:"+EdenLinkService.connection.token());assertFalse(feed.current(oldFrame));assertTrue(feed.current(frame("reader2",true)));assertFalse(feed.current(frame("reader1",false)));}
 @Test public void gameRestartBackgroundAndExpiredPresenceRejectPreviouslyHeldKeys(){String oldFrame=frame("reader1",true);var original=EdenLinkService.connection;long now=System.currentTimeMillis();EdenLinkService.connection=original.observed("456",true,now);assertFalse(feed.current(oldFrame));EdenLinkService.connection=original.observed("123",false,now);assertFalse(feed.current(oldFrame));EdenLinkService.connection=new GameConnection("123",true,now-7000,original.generation());assertFalse(feed.current(oldFrame));}
 @Test public void rotatingSourceClearsHeartbeatAndInvalidatesOldFrames()throws Exception{var watch=new java.io.File(context.getFilesDir(),"controller.watch");java.nio.file.Files.write(watch.toPath(),new byte[]{1});ReflectionHelpers.callInstanceMethod(feed,"rotate",ReflectionHelpers.ClassParameter.from(String.class,"default:newgame"));assertFalse(watch.exists());assertFalse(feed.current(frame("reader1",false)));assertFalse(feed.current("not json"));}
}
